enum PortError: Error { case notANumber(String), outOfRange(Int) }

func parsePort(_ text: String) -> Result<Int, PortError> {
    guard let port = Int(text) else { return .failure(.notANumber(text)) }
    guard (1...65535).contains(port) else { return .failure(.outOfRange(port)) }
    return .success(port)
}

switch parsePort(raw) {
case .success(let port): print("port", port)
case .failure(let error): print("invalid:", error)
}
